// render-yaml.ts — the purpose-built emitter of build-ci (spec 0262). It reproduces the
// shell's text byte for byte: fixed key order, double-quoted scalars escaped for `\` and
// `"` only, literal block scalars for multi-line commands, and the header/workflow text.
// Deliberately NOT a general YAML dump.

export const HEADER = `# .gitlab-ci.yml — GENERATED by scripts/build-ci.ts from ci/ci-capabilities.yml.
#
# DO NOT EDIT BY HAND. This pipeline is the derived GitLab form of the portable
# subset of the platform-neutral CI capability reference (spec 0048). Each job
# key IS a capability id (contract C2); each job's \`script:\` is the capability's
# declared \`command:\` (delta-01 R10); each job's \`image\`/\`before_script\`/
# \`GIT_DEPTH\` is the GitLab boilerplate satisfying the capability's \`requires:\`
# (delta-02 R12). Engine-specific capabilities (Pages, Releases, bot mentions)
# are deliberately absent — they stay hand-authored per engine (spec 0048 R4).
#
# To change a job, edit ci/ci-capabilities.yml and run:
#   node --disable-warning=MODULE_TYPELESS_PACKAGE_JSON scripts/build-ci.ts
# CI verifies this file is in sync via:
#   node --disable-warning=MODULE_TYPELESS_PACKAGE_JSON scripts/build-ci.ts --check
`;

/** The shared stage taxonomy, in pipeline order (spec 0287 R11). */
export const STAGES = `
stages:
  - gate
  - modules
  - governance
  - extensions
  - integration
  - windows
`;

export const WORKFLOW = `
workflow:
  rules:
    - if: '$CI_PIPELINE_SOURCE == "merge_request_event"'
    - if: '$CI_COMMIT_BRANCH && $CI_OPEN_MERGE_REQUESTS'
      when: never
    - if: '$CI_COMMIT_BRANCH'
`;

/** `esc_dq`: backslash-escape `\` then `"` for a double-quoted scalar. */
export function escDq(text: string): string {
  return text.replaceAll("\\", "\\\\").replaceAll('"', '\\"');
}

/** The line-reading loops of the shell: split on LF, drop empty lines. */
export function nonEmptyLines(text: string): string[] {
  return text.split("\n").filter((l) => l !== "");
}

/** `$(...)`: drop every trailing line feed. */
export function stripTrailingLf(text: string): string {
  return text.replace(/\n+$/, "");
}

/** A `- "<text>"` sequence item at `indent` spaces, escaped. */
export function dqItem(indent: number, text: string): string {
  return `${" ".repeat(indent)}- "${escDq(text)}"`;
}

/** A `key: "<text>"` mapping entry at `indent` spaces, escaped. */
export function dqEntry(indent: number, key: string, text: string): string {
  return `${" ".repeat(indent)}${key}: "${escDq(text)}"`;
}

/** A literal block scalar item: `- |` then each line at eight spaces, verbatim. */
export function blockItem(text: string): string[] {
  return ["    - |", ...text.split("\n").map((l) => `        ${l}`)];
}
